from pathlib import Path
root = Path(__file__).resolve().parents[1]
old = (root/'preview/index.html').read_text(encoding='utf-8')
css = old.split('<style>',1)[1].split('</style>',1)[0]
defs = old[old.index('<svg'):old.index("const NS=")]
# Keep only the existing SVG symbol/gradient definitions; page markup is replaced.
defs = defs[:defs.index('</svg>')+6]
js = old[old.index("const NS="):old.index("const left=new Wheel")]
js = js.replace("if(mode==='tools'&&this.category!=='image')", "if(false)")
html = '''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Naqla · صفحات الأدوات المعتمدة</title><style>'''+css+'''
body{padding:30px}main{max-width:1000px;padding:0}.proposal{padding:16px;border:1px solid #6f5534;background:#211c16;line-height:1.9}.choices{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.proposal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;direction:ltr}.proposal-card{padding:20px;background:#151c25;border:1px solid #344454;border-radius:16px;text-align:center}.at-size{width:240px;height:294px;margin:22px auto 0}.at-size .wheel-stage{transform:scale(.75);transform-origin:top left;margin:0}.page-caption{color:#ffc35a;font-size:13px;direction:rtl}.hint{color:#aab7c8;line-height:1.9}.controls{display:flex;gap:12px;justify-content:center;margin:20px}.navigation-dot{fill:#8190a2}.navigation-dot.current{fill:#ffc35a}@media(max-width:650px){body{padding:16px}.proposal-grid{grid-template-columns:1fr}h1{font-size:23px}}
</style><main><h1>صفحات الأدوات · التصميم المعتمد</h1><p class="proposal">مرجع المعاينة الذي وافقت عليه: ستة قطاعات كحد أقصى لكل صفحة، مع نقاط صغيرة داخل المركز. دُمج هذا التنقل في نسخة التطوير مع الحفاظ على شكل العجلة. هذه الصفحة عرض متصفح وليست اختبار سحب Windows.</p>
<p class="hint">Ctrl للتبديل بين تحويل وأدوات. داخل أدوات: Tab للتالي وShift + Tab للسابق. Esc يغلق. حُفظ Drag + Shift. وافقت على هذا التنقل؛ اختباره الفعلي أثناء OLE يبقى ضمن قائمة Windows اليدوية.</p>
<div class="choices" id="choices"></div><div class="proposal-grid"><section class="proposal-card"><div class="page-caption" id="caption-a"></div><div class="at-size"><div id="a" class="wheel-stage"></div></div></section><section class="proposal-card"><div class="page-caption" id="caption-b"></div><div class="at-size"><div id="b" class="wheel-stage"></div></div></section></div>
<div class="controls"><button class="secondary" id="prev">السابقة</button><button class="primary" id="next">التالية · Tab</button></div><p class="hint" id="status">يمكن تجربة الصفحات بالأزرار أو لوحة المفاتيح. اختيار قطاع لا يعالج ملفات.</p><p class="hint">الأدوات مرتبطة بقدرات الملف والحزم المحلية المثبتة؛ في التطبيق لن يظهر خيار غير متاح. هذه المعاينة تُظهر توزيعًا مقترحًا عند توافر المحركات.</p></main>'''+defs+'<script>'+js+'''
const sets={image:[['ضغط','compress'],['حجم مستهدف','compress'],['قص','crop'],['تدوير','rotate'],['بدون بيانات','privacy'],['تسمية','merge'],['إزالة الخلفية','crop'],['استخراج نص','merge'],['تنظيف خصوصية','privacy'],['أرشفة','merge'],['SHA-256','privacy']],video:[['ضغط','compress'],['تدوير','rotate'],['بدون صوت','privacy'],['بدون بيانات','privacy'],['تسمية','merge'],['قص زمني','crop'],['إطارات','image'],['ترجمة نصية','merge'],['تنظيف خصوصية','privacy'],['أرشفة','merge'],['SHA-256','privacy']],audio:[['ضغط','compress'],['بدون بيانات','privacy'],['تسمية','merge'],['قص زمني','crop'],['تطبيع الصوت','compress'],['قص الصمت','crop'],['القنوات','merge'],['ترجمة نصية','merge'],['تنظيف خصوصية','privacy'],['أرشفة','merge'],['SHA-256','privacy']],pdf:[['استخراج نص','merge'],['ترتيب','crop'],['استخراج','merge'],['حذف','crop'],['ترقيم','merge'],['علامة مائية','privacy'],['تدوير','rotate'],['تسمية','merge'],['OCR','merge'],['تنظيف خصوصية','privacy'],['أرشفة','merge'],['SHA-256','privacy']]};
let current='image',page=0;const a=new Wheel('a','image','tools'),b=new Wheel('b','image','tools');
function dots(w,p,total){const g=node('g',{'aria-label':`صفحة ${p+1} من ${total}`});for(let i=0;i<total;i++)g.append(node('rect',{x:160+(i-(total-1)/2)*11-2,y:214,width:4,height:4,class:'navigation-dot'+(i===p?' current':'')}));w.hub.append(g)}
function paint(){const pages=Math.ceil(sets[current].length/6);for(const [w,p,id] of [[a,page,'a'],[b,(page+1)%pages,'b']]){w.category=current;w.mode='tools';tools.splice(0,tools.length,...sets[current].slice(p*6,p*6+6));w.renderHub();w.paint();dots(w,p,pages);document.getElementById('caption-'+id).textContent=`${files[current].title} · صفحة ${p+1} / ${pages}`;}document.getElementById('status').textContent='مرجع التنقل المعتمد · Tab للتالي وShift+Tab للسابق؛ Ctrl مستقل لتبديل الوضع.';}
function turn(delta){page=(page+delta+Math.ceil(sets[current].length/6))%Math.ceil(sets[current].length/6);paint()}
for(const [id,file] of Object.entries(files)){const button=document.createElement('button');button.className='secondary';button.textContent=file.title;button.onclick=()=>{current=id;page=0;paint()};document.getElementById('choices').append(button)}
document.getElementById('next').onclick=()=>turn(1);document.getElementById('prev').onclick=()=>turn(-1);
window.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();turn(e.shiftKey?-1:1)}if(e.key==='Escape'){a.host.classList.add('closed');b.host.classList.add('closed')}});paint();
</script></html>'''
(root/'preview/tools-pagination.html').write_text(html,encoding='utf-8')
